  name: "Dashboard - Combined Charts",
  render: () => <div className="space-y-8">
      <h2 className="text-2xl font-bold">Analytics Dashboard</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="p-4 border rounded-lg bg-card">
          <h3 className="text-lg font-semibold mb-4">Monthly Revenue</h3>
          <BarChart data={monthlyData} xAxisKey="month" bars={[{
          dataKey: "revenue",
          name: "Revenue"
        }]} height={250} showLegend={false} />
        </div>

        <div className="p-4 border rounded-lg bg-card">
          <h3 className="text-lg font-semibold mb-4">Sales Trend</h3>
          <LineChart data={monthlyData} xAxisKey="month" lines={[{
          dataKey: "sales",
          name: "Sales"
        }]} height={250} showLegend={false} />
        </div>

        <div className="p-4 border rounded-lg bg-card">
          <h3 className="text-lg font-semibold mb-4">Product Distribution</h3>
          <DonutChart data={categoryData} height={250} />
        </div>

        <div className="p-4 border rounded-lg bg-card">
          <h3 className="text-lg font-semibold mb-4">Performance Over Time</h3>
          <AreaChart data={monthlyData} xAxisKey="month" areas={[{
          dataKey: "profit",
          name: "Profit"
        }]} height={250} showLegend={false} />
        </div>
      </div>
    </div>
